check_names and check_columns let you inspect a checkset programmatically: checks = @checkset "Order Consistency" begin
    @check "Ships on or after order" ((o, s) -> s >= o)(:order_date, :ship_date)
    @check "Positive quantity" (q -> q > 0)(:quantity)
end

