Because results are plain values, a checkset can serve as a data contract in your tests: using Test, CheckMate

const ORDER_CONTRACT = @checkset "Order contract" begin
    @check "Positive quantity" (q -> q > 0)(:quantity)
    @check "Known status"      (s -> s in ("open", "shipped", …

